<?php $row=($presentation??'card')==='row';$thumbnail=$entry['kind']==='article'?(string)$s->get('article_thumbnail'):'left';$withCover=$thumbnail!=='text' && (!empty($entry['cover_id']) || !empty($entry['cover_art'])); ?>
<article class="content-card card glass reveal <?= $row?'article-row':'' ?> <?= $thumbnail==='right'?'thumbnail-right':'' ?> <?= !$withCover?'without-cover':'' ?>" data-content-id="<?= (int)$entry['id'] ?>"><?php if($withCover): ?><a class="card-cover" aria-label="<?= e($entry['title']) ?>" href="<?= e(item_url($entry)) ?>"><img src="<?= e(cover($entry)) ?>" alt="" loading="lazy" width="640" height="440"><?php if ($entry['access_level'] !== 'public'): ?><span class="cover-badge"><?= icon('lock') ?><?= t($entry['access_level'] === 'paid' ? 'Paid access' : $entry['access_level']) ?></span><?php endif ?></a><?php endif ?><div class="card-content"><div class="card-kicker"><?php if(!$withCover && $entry['access_level']!=='public'): ?><span class="entry-access"><?= icon('lock') ?><?= t($entry['access_level']==='paid'?'Paid access':$entry['access_level']) ?></span><?php endif ?><span><?= e($entry['category_name'] ?: tr($entry['kind'])) ?></span><?php if ($s->get('show_dates')): ?><time datetime="<?= e(date('c',(int)$entry['created_at'])) ?>"><?= dt((int)$entry['created_at'],'Y-m-d') ?></time><?php endif ?></div><h3 class="card-title"><?php if((int)$entry['pinned']): ?><span class="entry-status"><?= t('Pinned') ?></span><?php endif ?><a href="<?= e(item_url($entry)) ?>"><?= e($entry['title']) ?></a></h3><p class="card-excerpt"><?= e($entry['excerpt']) ?></p><?php if ($entry['kind'] === 'product'): ?><div class="card-price"><?= e(item_price($entry)) ?><small><?= (int)$entry['sold_count'] ?> <?= t('sold') ?></small></div><?php endif ?><div class="card-meta"><?php if ($s->get('show_authors')): ?><a class="author" href="<?= e(url('user',['id'=>(int)$entry['author_id']])) ?>"><?= avatar($entry,'tiny') ?><span><?= e($entry['display_name']) ?></span></a><?php endif ?><?php if ($s->get('show_stats')): ?><span class="meta-right"><?= icon('eye') ?><?= number_format((int)$entry['view_count']) ?></span><?php endif ?></div></div></article>
